// The production makers behind depiction tiers 2 to 4 (engine/design/depict): a sprite generated by Muse Image in the
// video's style and cut into parts with SAM, and a real picture (the user's own, or one found in the archives) read into
// a PartCard by Spark with SAM masks where asked. The scene stage calls them; the engine only sees SpriteMaker and a
// PartCard, so tests plug in fakes. Every paid call goes through `charge`, and a maker that fails throws a clear error:
// nothing lesser is swapped in. A problem the model can fix (a part SAM cannot find, a reading that does not check) goes
// back to the model first, for a set number of rounds.
//
// Masks are worked in plain TypeScript (SAM's box-sized rasters placed into the picture, PNGs written with zlib), and
// pictures are decoded and scaled with ffmpeg, as the rest of the pipeline does. No Python is needed.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, extname, join, resolve } from "node:path";
import { crc32, deflateSync } from "node:zlib";
import { decodeMaskToRaster, parseImageStream, recordsOfKind, type ResponsesEvent } from "@meta-sam/parser";
import type { SpriteMaker, SpriteRequest } from "../../engine/design/depict/sprite.ts";
import { CHECK, checkCard } from "../../engine/design/material/check.ts";
import { cardFromPicture, pictureSchema, pictureTask, repairTask, type PictureAnswer } from "../../engine/design/material/picture.ts";
import type { Box, PartCard, Reasoner } from "../../engine/design/types.ts";
import type { StyleFile } from "../../schemas/project.ts";
import { download as fetchFile, MIN_SIDE, searchArchives, type Candidate } from "./archives.ts";
import { json, post, PRICE } from "./meta.ts";

/**
 * What the scene stage is handed to make tiers 2 to 4. `sprite` makes a generated picture and its part masks (used
 * through getSprite, which caches by description and style and asks only when the designer allowed it). `picture`
 * returns a real picture with the named parts found: the user's own file when `asset` is given (tier 3), else one the
 * archives hold for `desc` (tier 4, with its credit in `found`); its result goes straight to pictureDepiction
 * (`card`, `src`, and `masks` for parts asked with `mask`).
 */
export type DepictMakers = {
  sprite?: SpriteMaker;
  picture?: (desc: string, asset?: string, parts?: PictureAsk[]) => Promise<PictureMade>;
};

/** A part the video needs of a picture: its name in the plan, what it is, and whether to cut a SAM mask for it. */
export type PictureAsk = { name: string; about?: string; phrase?: string; mask?: boolean };
export type PictureMade = { card: PartCard; src: string; masks?: Record<string, string>; missing: string[]; tier: 3 | 4; found?: Found };
/** A picture found in the archives, with what is needed to credit it. */
export type Found = { path: string; title: string; source: string; license: string; credit: string; page: string; why: string };

/** Spend: every paid call is charged as it is made, and the budget is asked before it. */
export type Spend = { charge?: (usd: number, detail: string) => void; checkBudget?: (estimate: number) => void };

/** One SAM mask: a raster the size of its box (1 where the thing is), the box in pixels of the picture sent. */
export type SamMask = { raster: Uint8Array; width: number; height: number; bounds: { left: number; top: number; right: number; bottom: number }; confidence?: number };
/** Every mask SAM returns for a phrase on a picture file, and what it cost. */
export type Segmenter = (file: string, phrase: string) => Promise<{ masks: SamMask[]; usd: number }>;
/** A picture made from a prompt (any image format ffmpeg reads), and what it cost. `study` is a look reference. */
export type ImageMaker = (prompt: string, study?: string) => Promise<{ png: Buffer; usd: number }>;

/** The style a sprite is drawn in: objects use the style's own description of how its object pictures look. */
export const spriteStyle = (s: StyleFile) => ({ name: s.name, art: s.art.object });

export const PICTURE_CACHE = "projects/cache/pictures";
export const FOUND_CACHE = "projects/cache/found";
// SAM is sent pictures this size at most on the long side (as assets.ts does); its masks come back at most 1024 px.
const SAM_SIDE = 1600;

// ---------------------------------------------------------------------------------------------------------------------
// The Meta calls.

const mime = (file: string) => ({ ".png": "image/png", ".webp": "image/webp" })[extname(file).toLowerCase()] ?? "image/jpeg";
const dataUrl = (file: string) => `data:${mime(file)};base64,${readFileSync(file).toString("base64")}`;

// The SAM parser reads a Responses event stream; a non-streamed reply is replayed as one delta (as in assets.ts).
async function* asEvents(text: string): AsyncIterable<ResponsesEvent> {
  const lane = { item_id: "m", output_index: 0, content_index: 0 };
  yield { type: "response.output_text.delta", ...lane, delta: text } as ResponsesEvent;
  yield { type: "response.output_text.done", ...lane, text } as ResponsesEvent;
  yield { type: "response.completed" } as ResponsesEvent;
}

/** SAM 3.1 on Meta: every mask for a phrase. No match is an empty list, not an error (spike S4). */
export const samSegment: Segmenter = async (file, phrase) => {
  const r = await post("/responses", {
    model: "sam-3.1",
    store: false,
    metadata: { include_confidence: "true", mask_encoding: "lossless" },
    input: [{ role: "user", content: [{ type: "input_image", image_url: dataUrl(file) }, { type: "input_text", text: phrase }] }],
  });
  const text = r.output?.[0]?.content?.[0]?.text ?? "";
  const records = recordsOfKind((await parseImageStream(asEvents(text)).finalResult).records, "mask") as any[];
  return { masks: records.map((m) => ({ raster: decodeMaskToRaster(m.mask), width: m.mask.width, height: m.mask.height, bounds: { ...m.bounds }, confidence: m.confidence })), usd: PRICE.sam };
};

/** Muse Image on Meta: one square PNG from the prompt; with a look study, through /images/edits (spike S2). */
export const museImage: ImageMaker = async (prompt, study) => {
  const fields = { model: "muse-image-1.0", size: "1024x1024", n: 1, response_format: "b64_json", output_format: "png", reasoning_strength: "low", tool_enablement: { enable_web_search: false, enable_image_search: false, enable_shell: false } };
  let r: any;
  if (study) {
    const form = new FormData();
    const text = `Use the reference image only for its look: medium, palette, lighting, line and texture. Do not copy its subjects, objects or layout. ${prompt}`;
    for (const [k, v] of Object.entries({ ...fields, prompt: text })) form.append(k, typeof v === "object" ? JSON.stringify(v) : String(v));
    form.append("image[0]", new Blob([readFileSync(study)], { type: mime(study) }), basename(study));
    r = await post("/images/edits", form);
  } else r = await post("/images/generations", { ...fields, prompt });
  const b64 = r.data?.[0]?.b64_json;
  if (!b64) throw new Error("muse image returned no image");
  return { png: Buffer.from(b64, "base64"), usd: PRICE.image };
};

// ---------------------------------------------------------------------------------------------------------------------
// Pictures and masks in plain code.

type Raster = { w: number; h: number; on: Uint8Array };

function dims(file: string): [number, number] {
  const out = execFileSync("ffprobe", ["-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height", "-of", "csv=p=0", file]).toString().trim();
  const [w, h] = out.split(",").map(Number);
  if (!w || !h) throw new Error(`cannot read the size of ${file}`);
  return [w, h];
}

/** The picture scaled to fit SAM (never up), as a PNG to work from and a JPEG to send, with its pixels as RGBA. */
function workCopy(src: string, dir: string): { png: string; jpg: string; w: number; h: number; rgba: Buffer } {
  const png = join(dir, "work.png");
  const jpg = join(dir, "work.jpg");
  const fit = `scale='min(${SAM_SIDE},iw)':'min(${SAM_SIDE},ih)':force_original_aspect_ratio=decrease:flags=lanczos`;
  execFileSync("ffmpeg", ["-y", "-v", "error", "-i", src, "-vf", fit, "-frames:v", "1", "-update", "1", png]);
  execFileSync("ffmpeg", ["-y", "-v", "error", "-i", png, "-q:v", "3", "-frames:v", "1", "-update", "1", jpg]);
  const [w, h] = dims(png);
  const rgba = execFileSync("ffmpeg", ["-v", "error", "-i", png, "-f", "rawvideo", "-pix_fmt", "rgba", "-"], { maxBuffer: 1 << 30 });
  if (rgba.length !== w * h * 4) throw new Error(`decoding ${src}: ${rgba.length} bytes for ${w}x${h}`);
  return { png, jpg, w, h, rgba };
}

/** A SAM mask placed into the whole picture (nearest pixel: SAM's raster is at most 1024 px, scaled to its box). */
export function placeMask(m: SamMask, w: number, h: number): Raster {
  const on = new Uint8Array(w * h);
  const { left, top, right, bottom } = m.bounds;
  const bw = right - left;
  const bh = bottom - top;
  if (bw <= 0 || bh <= 0) return { w, h, on };
  for (let y = Math.max(0, Math.floor(top)); y < Math.min(h, Math.ceil(bottom)); y++) {
    const my = Math.min(m.height - 1, Math.floor(((y - top) * m.height) / bh));
    for (let x = Math.max(0, Math.floor(left)); x < Math.min(w, Math.ceil(right)); x++) {
      const mx = Math.min(m.width - 1, Math.floor(((x - left) * m.width) / bw));
      if (m.raster[my * m.width + mx]) on[y * w + x] = 1;
    }
  }
  return { w, h, on };
}

const area = (r: Raster) => r.on.reduce((n, v) => n + v, 0);
const both = (a: Raster, b: Raster) => a.on.reduce((n, v, i) => n + (v & b.on[i]!), 0);

/** The pixel box of what is on, inclusive, or undefined for an empty raster. */
function extent(r: Raster): [number, number, number, number] | undefined {
  let [x0, y0, x1, y1] = [r.w, r.h, -1, -1];
  for (let y = 0; y < r.h; y++) for (let x = 0; x < r.w; x++) if (r.on[y * r.w + x]) (x0 = Math.min(x0, x), y0 = Math.min(y0, y), x1 = Math.max(x1, x), y1 = Math.max(y1, y));
  return x1 < 0 ? undefined : [x0, y0, x1, y1];
}

function crop(r: Raster, [x0, y0, x1, y1]: [number, number, number, number]): Raster {
  const w = x1 - x0 + 1;
  const h = y1 - y0 + 1;
  const on = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) on.set(r.on.subarray((y + y0) * r.w + x0, (y + y0) * r.w + x0 + w), y * w);
  return { w, h, on };
}

/** A PNG from 8-bit gray (1 channel) or RGBA (4 channels) pixels. */
export function encodePng(w: number, h: number, channels: 1 | 4, px: Uint8Array): Buffer {
  const row = w * channels;
  const raw = Buffer.alloc((row + 1) * h);
  for (let y = 0; y < h; y++) raw.set(px.subarray(y * row, (y + 1) * row), y * (row + 1) + 1);
  const chunk = (type: string, data: Buffer) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length);
    const body = Buffer.concat([Buffer.from(type, "latin1"), data]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(body) >>> 0);
    return Buffer.concat([len, body, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0);
  ihdr.writeUInt32BE(h, 4);
  ihdr.set([8, channels === 1 ? 0 : 6, 0, 0, 0], 8);
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk("IHDR", ihdr), chunk("IDAT", deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]);
}

const maskPng = (r: Raster) => encodePng(r.w, r.h, 1, r.on.map((v) => v * 255));
const round4 = (x: number) => Math.round(x * 10000) / 10000;
const fracBox = (r: Raster): [number, number, number, number] => {
  const e = extent(r)!;
  return [round4(e[0] / r.w), round4(e[1] / r.h), round4((e[2] + 1) / r.w), round4((e[3] + 1) / r.h)];
};

/**
 * Where a part joins the rest of the thing: the middle of the part's edge pixels that have the rest of the thing within
 * `reach` pixels outside them (a lid's hinge, an arm's shoulder). Undefined when the part touches nothing, so a free
 * part turns about its own middle.
 */
export function joint(part: Raster, whole: Raster, reach: number): [number, number] | undefined {
  const { w, h } = part;
  const rest = (x: number, y: number) => x >= 0 && y >= 0 && x < w && y < h && whole.on[y * w + x] === 1 && part.on[y * w + x] === 0;
  let [sx, sy, n] = [0, 0, 0];
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    if (!part.on[y * w + x]) continue;
    let touches = false;
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) for (let k = 1; k <= reach && !touches; k++) {
      const [px, py] = [x + dx * k, y + dy * k];
      if (px >= 0 && py >= 0 && px < w && py < h && part.on[py * w + px]) break; // still inside the part
      if (rest(px, py)) touches = true;
    }
    if (touches) (sx += x + 0.5, sy += y + 0.5, n++);
  }
  return n ? [round4(sx / n / w), round4(sy / n / h)] : undefined;
}

// ---------------------------------------------------------------------------------------------------------------------
// Tier 2: sprites.

export type SpriteMakerOptions = Spend & {
  image?: ImageMaker;
  segment?: Segmenter;
  /** A look study of this video's generated objects (assets.ts makes one per image type), so sprites share one look. */
  study?: string;
  /** Pictures made in all: the first, plus repairs when SAM cannot find the thing or a part in it. */
  rounds?: number;
  /** A part whose mask covers this share of the whole thing is the whole thing, not a part. */
  wholeShare?: number;
};

/** What went wrong with one generated picture, in words the next prompt can carry. */
class SpriteProblems extends Error {
  problems: string[];
  constructor(problems: string[]) {
    super(problems.join("; "));
    this.problems = problems;
  }
}

/**
 * The production sprite maker: Muse Image draws the thing from the request's prompt (written from the style's own art
 * description by spriteRequest), SAM finds the whole thing (its mask becomes the sprite's alpha, and the sprite is
 * cropped to it) and each part by its phrase. A picture SAM cannot read is made again with what was wrong, up to
 * `rounds`; after that the maker throws with every problem.
 */
export function metaSpriteMaker(opts: SpriteMakerOptions = {}): SpriteMaker {
  const image = opts.image ?? museImage;
  const segment = opts.segment ?? samSegment;
  const rounds = Math.max(1, opts.rounds ?? 2);
  const wholeShare = opts.wholeShare ?? 0.9;
  const paid = async <T extends { usd: number }>(estimate: number, detail: string, f: () => Promise<T>): Promise<T> => {
    opts.checkBudget?.(estimate);
    const r = await f();
    if (r.usd) opts.charge?.(r.usd, detail);
    return r;
  };
  return {
    async make(req: SpriteRequest) {
      let prompt = req.prompt;
      const seen: string[] = [];
      for (let round = 1; ; round++) {
        const made = await paid(PRICE.image, `sprite ${req.key} image${round > 1 ? ` (repair ${round - 1})` : ""}`, () => image(prompt, opts.study));
        const dir = mkdtempSync(join(tmpdir(), "sprite-"));
        try {
          const src = join(dir, "made");
          writeFileSync(src, made.png);
          const pic = workCopy(src, dir);
          const phrases = [req.label, ...req.parts.map((p) => p.phrase)];
          const found = await Promise.all(phrases.map((ph) => paid(PRICE.sam, `sprite ${req.key} sam "${ph}"`, () => segment(pic.jpg, ph))));
          return cutSprite(req, pic, found.map((f) => f.masks), wholeShare);
        } catch (e) {
          if (!(e instanceof SpriteProblems)) throw e;
          seen.push(...e.problems);
          if (round >= rounds) throw new Error(`sprite "${req.desc}" (${req.style}): SAM could not cut it after ${rounds} picture${rounds > 1 ? "s" : ""}: ${seen.join("; ")}`);
          prompt = `${req.prompt} The last picture could not be used: ${e.problems.join("; ")}. Make sure of it this time.`;
        } finally {
          rmSync(dir, { recursive: true, force: true });
        }
      }
    },
  };
}

/** The sprite from one picture and SAM's masks: the thing's own mask as alpha, cropped to it, and a mask per part. */
function cutSprite(req: SpriteRequest, pic: { w: number; h: number; rgba: Buffer }, found: SamMask[][], wholeShare: number) {
  const { w, h } = pic;
  const problems: string[] = [];
  const best = (ms: SamMask[]) => [...ms].sort((a, b) => (b.confidence ?? 0) - (a.confidence ?? 0))[0];
  const objMask = best(found[0]!);
  const obj = objMask ? placeMask(objMask, w, h) : undefined;
  if (!obj || !area(obj)) throw new SpriteProblems([`SAM found no "${req.label}" in the picture: it must be one plain, whole ${req.label}`]);
  if (area(obj) > 0.95 * w * h) throw new SpriteProblems([`the "${req.label}" filled the whole picture: it must stand alone on a plain background with space around it`]);
  const parts: Record<string, Raster> = {};
  req.parts.forEach((p, i) => {
    // The part's mask must lie in the thing (SAM may also find the phrase in the background), and must not be the thing.
    const inside = found[i + 1]!.map((m) => ({ m, r: placeMask(m, w, h) })).filter(({ r }) => area(r) && both(r, obj) >= 0.5 * area(r));
    const pick = inside.sort((a, b) => (b.m.confidence ?? 0) - (a.m.confidence ?? 0))[0];
    if (!pick) return void problems.push(`SAM found no "${p.phrase}" on the ${req.label}: it must be plainly visible as its own piece`);
    if (area(pick.r) >= wholeShare * area(obj)) return void problems.push(`"${p.phrase}" could not be told apart from the whole ${req.label}: it must be a clearly separate piece`);
    parts[p.name] = pick.r;
  });
  if (problems.length) throw new SpriteProblems(problems);
  // Everything that is the thing: its own mask and its parts' (a part SAM drew a little past the outline stays whole).
  const all: Raster = { w, h, on: obj.on.slice() };
  for (const r of Object.values(parts)) for (let i = 0; i < all.on.length; i++) all.on[i] |= r.on[i]!;
  const e = extent(all)!;
  const pad = 2;
  const box: [number, number, number, number] = [Math.max(0, e[0] - pad), Math.max(0, e[1] - pad), Math.min(w - 1, e[2] + pad), Math.min(h - 1, e[3] + pad)];
  const keep = crop(all, box);
  const [cw, ch] = [keep.w, keep.h];
  const rgba = new Uint8Array(cw * ch * 4);
  for (let y = 0; y < ch; y++) for (let x = 0; x < cw; x++) {
    const s = ((y + box[1]) * w + x + box[0]) * 4;
    const d = (y * cw + x) * 4;
    rgba.set(pic.rgba.subarray(s, s + 3), d);
    rgba[d + 3] = keep.on[y * cw + x] ? pic.rgba[s + 3]! : 0;
  }
  const reach = Math.max(2, Math.round(0.01 * Math.max(cw, ch)));
  const masks: Record<string, { png: Buffer; box: [number, number, number, number]; anchor?: [number, number] }> = {};
  for (const p of req.parts) {
    const r = crop(parts[p.name]!, box);
    const anchor = p.changes.includes("turn") ? joint(r, keep, reach) : undefined;
    masks[p.name] = { png: maskPng(r), box: fracBox(r), ...(anchor ? { anchor } : {}) };
  }
  return { png: encodePng(cw, ch, 4, rgba), size: [cw, ch] as [number, number], masks };
}

// ---------------------------------------------------------------------------------------------------------------------
// Tiers 3 and 4: real pictures.

export type PictureOptions = Spend & {
  /** Spark (metaReasoner) in production; it is charged through its own `charge`. */
  reasoner: Reasoner;
  segment?: Segmenter;
  /** The name the plan uses for the picture; the file's name by default. */
  name?: string;
  /** What the user or the archive said about the picture. */
  about?: string;
  /** Repair rounds for a reading that does not check. */
  rounds?: number;
  /** A SAM mask counts as the reader's part when it overlaps the reader's box at least this much (intersection over union). */
  minOverlap?: number;
  root?: string;
};

const asksKey = (parts: PictureAsk[]) => [...parts].sort((a, b) => a.name.localeCompare(b.name)).map((p) => [p.name, p.about ?? "", p.phrase ?? "", !!p.mask]);
export const pictureKey = (file: string, parts: PictureAsk[]) => createHash("sha1").update(readFileSync(file)).update(JSON.stringify(asksKey(parts))).digest("hex").slice(0, 16);

const pictureAnswerSchema = {
  ...pictureSchema,
  required: [...pictureSchema.required, "missing"],
  properties: { ...pictureSchema.properties, missing: { type: "array", items: { type: "string" }, description: "the names of the parts asked for that this picture does not show" } },
};

const wantedText = (parts: PictureAsk[]) =>
  parts.length
    ? `\n\nThe video needs these parts of the picture, under exactly these names. Give each one it shows its box; name any it does not show in \`missing\` rather than guess where it would be. Add any other parts you see as usual.\n${parts.map((p) => `- ${p.name}${p.about ? `: ${p.about}` : ""}`).join("\n")}`
    : "\n\nNo particular parts were asked for: give every part as usual, and an empty `missing`.";

export class Pending extends Error {
  file: string;
  constructor(file: string) {
    super(`the reading of the picture is pending: ${file}`);
    this.file = file;
  }
}

/**
 * A real picture read into a PartCard with the parts the video needs (Spark, as the material readers do, repaired until
 * it checks or the rounds run out), and a SAM mask for each asked part with `mask`, chosen as the mask that best matches
 * the reader's box. Cached by the picture's bytes and the parts asked. A part the picture does not show is in
 * `missing`; a mask SAM cannot find is an error.
 */
export async function pictureParts(src: string, parts: PictureAsk[], opts: PictureOptions, tier: 3 | 4 = 3): Promise<PictureMade> {
  const path = resolve(src);
  const dir = resolve(opts.root ?? PICTURE_CACHE, pictureKey(path, parts));
  const saved = join(dir, "card.json");
  if (existsSync(saved)) return { ...(JSON.parse(readFileSync(saved, "utf8")) as Omit<PictureMade, "tier">), src: path, tier };
  const size = dims(path);
  const file = { name: opts.name ?? basename(path, extname(path)), file: basename(path), path, size, ...(opts.about ? { about: opts.about } : {}) };
  const base = pictureTask(file, `read.${file.name}.parts`);
  let task = { ...base, request: base.request + wantedText(parts), schema: pictureAnswerSchema as unknown as Record<string, unknown> };
  const rounds = opts.rounds ?? 3;
  let card!: PartCard;
  let missing!: string[];
  for (let round = 0; ; round++) {
    const a = await opts.reasoner.ask<PictureAnswer & { missing: string[] }>(task);
    if (a.status === "pending") throw new Pending(a.file);
    card = cardFromPicture(file, a.value);
    missing = parts.map((p) => p.name).filter((n) => (a.value.missing ?? []).includes(n) && !card.parts[n]?.box);
    const problems = [
      ...checkCard(card, {}, CHECK),
      ...parts.filter((p) => !card.parts[p.name]?.box && !missing.includes(p.name)).map((p) => `the part "${p.name}" was asked for but has no box and is not named in missing`),
    ];
    if (!problems.length || round >= rounds) {
      card.checked = { ok: !problems.length, notes: problems.length ? problems : [round ? `checked after ${round} repair${round > 1 ? "s" : ""}` : "checked"] };
      break;
    }
    task = { ...repairTask(task, a.value, problems, round + 1), schema: task.schema };
  }
  let masks: Record<string, string> | undefined;
  const cut = parts.filter((p) => p.mask && card.parts[p.name]?.box);
  if (cut.length) {
    masks = {};
    const segment = opts.segment ?? samSegment;
    const work = mkdtempSync(join(tmpdir(), "picture-"));
    try {
      const pic = workCopy(path, work);
      mkdirSync(join(dir, "masks"), { recursive: true });
      const minOverlap = opts.minOverlap ?? 0.3;
      for (const p of cut) {
        opts.checkBudget?.(PRICE.sam);
        const phrase = p.phrase ?? p.name;
        const r = await segment(pic.jpg, phrase);
        if (r.usd) opts.charge?.(r.usd, `picture ${file.name} sam "${phrase}"`);
        const [bx0, by0, bx1, by1] = card.parts[p.name]!.box as Box;
        const want = { x0: bx0 * pic.w, y0: by0 * pic.h, x1: bx1 * pic.w, y1: by1 * pic.h };
        const scored = r.masks.map((m) => {
          const placed = placeMask(m, pic.w, pic.h);
          const e = extent(placed);
          if (!e) return { placed, iou: 0 };
          const [x0, y0, x1, y1] = [e[0], e[1], e[2] + 1, e[3] + 1];
          const iw = Math.max(0, Math.min(x1, want.x1) - Math.max(x0, want.x0));
          const ih = Math.max(0, Math.min(y1, want.y1) - Math.max(y0, want.y0));
          const inter = iw * ih;
          return { placed, iou: inter / ((x1 - x0) * (y1 - y0) + (want.x1 - want.x0) * (want.y1 - want.y0) - inter) };
        });
        const top = scored.sort((a, b) => b.iou - a.iou)[0];
        if (!top || top.iou < minOverlap) {
          throw new Error(`picture ${file.name}: SAM found no "${phrase}" where the reader boxed the ${p.name} (${r.masks.length} mask${r.masks.length === 1 ? "" : "s"}, best overlap ${(top?.iou ?? 0).toFixed(2)}); ask with another phrase or without a mask`);
        }
        const out = join(dir, "masks", `${p.name}.png`);
        writeFileSync(out, maskPng(top.placed));
        masks[p.name] = out;
      }
    } finally {
      rmSync(work, { recursive: true, force: true });
    }
  }
  const made = { card, src: path, ...(masks ? { masks } : {}), missing };
  mkdirSync(dir, { recursive: true });
  writeFileSync(saved, JSON.stringify(made, null, 1));
  return { ...made, tier };
}

// ---------------------------------------------------------------------------------------------------------------------
// Finding a picture of a thing.

export type FindOptions = Spend & {
  /** Archive searches; the description itself by default. */
  queries?: string[];
  search?: (q: string) => Promise<Candidate[]>;
  download?: (url: string) => Promise<Uint8Array>;
  /** The look at the candidates. Production asks Spark (see PICK_THING); tests plug in a fake. */
  pick?: (desc: string, cands: { c: Candidate; b64: string }[]) => Promise<{ pick: number | null; reason: string; usd: number }>;
  /** How many candidates are looked at, at most. */
  from?: number;
  root?: string;
};

export const PICK_THING =
  "You choose a real picture of one thing for a video that will show it and point at its parts. For each candidate, first say plainly what it actually shows: the kind of thing, and whether it is a photograph, a period drawing, map or document, a modern painting or illustration, a replica, a scale model or toy, a museum panel, or clip art. Then judge it against the description.\n" +
  "A candidate is usable only if all of these hold:\n" +
  "- It shows the very thing described, not a relative of it, another model of it or something that only shares its name.\n" +
  "- The thing is whole and clear enough to point at its parts, and is the subject of the picture, not a detail of a crowded scene.\n" +
  "- It is honest about what it is: a model, replica or illustration is usable only when the description allows one.\n" +
  "- Nothing visible contradicts the description (a label, a date, a place).\n" +
  "Pick the candidate that shows the thing most directly, then the clearest. Answer null when none passes: a near miss is not usable. In `reason`, say in one or two plain sentences why the pick fits, or why none does.";

const sparkPick: NonNullable<FindOptions["pick"]> = async (desc, cands) => {
  const r = await json<{ candidates: { n: number; shows: string; fits: boolean }[]; pick: number | null; reason: string }>({
    system: PICK_THING,
    user: [
      ...cands.flatMap(({ c, b64 }, k) => [
        { type: "input_text", text: `Candidate ${k} (${c.source}, ${c.license}${c.size ? `, ${c.size}` : ""}): ${c.title}` },
        { type: "input_image", image_url: `data:image/jpeg;base64,${b64}` },
      ]),
      { type: "input_text", text: `The thing to show: ${desc}\nPick the best candidate, or null if none is usable.` },
    ],
    schema: {
      type: "object",
      additionalProperties: false,
      required: ["candidates", "pick", "reason"],
      properties: {
        candidates: { type: "array", items: { type: "object", additionalProperties: false, required: ["n", "shows", "fits"], properties: { n: { type: "integer" }, shows: { type: "string" }, fits: { type: "boolean" } } } },
        pick: { type: ["integer", "null"] },
        reason: { type: "string" },
      },
    },
    schemaName: "thing_pick",
  });
  return { pick: r.value.pick, reason: r.value.reason, usd: r.usd };
};

/**
 * A real picture of a described thing from the open archives (archives.ts: public domain and CC only), looked at by
 * Spark against the description, downloaded and kept with its credit. Cached by description. Throws when nothing
 * honest is found: the caller then asks the depicter for another tier.
 */
export async function findPicture(desc: string, opts: FindOptions = {}): Promise<Found> {
  const dir = resolve(opts.root ?? FOUND_CACHE, createHash("sha1").update(desc.trim().toLowerCase()).digest("hex").slice(0, 16));
  const meta = join(dir, "found.json");
  if (existsSync(meta)) return JSON.parse(readFileSync(meta, "utf8")) as Found;
  const search = opts.search ?? ((q: string) => searchArchives(q));
  const get = opts.download ?? fetchFile;
  const queries = opts.queries?.length ? opts.queries : [desc];
  const lists = await Promise.all(queries.map((q) => search(q)));
  const cands: Candidate[] = [];
  for (const c of lists.flat()) if (!cands.some((x) => x.full === c.full)) cands.push(c);
  const shown = cands.slice(0, opts.from ?? 10);
  const thumbs = await Promise.all(shown.map((c) => get(c.thumb).then((b) => ({ c, b64: Buffer.from(b).toString("base64") })).catch(() => null)));
  const ok = thumbs.filter((t): t is { c: Candidate; b64: string } => !!t);
  if (!ok.length) throw new Error(`findPicture "${desc}": the archives returned nothing for ${queries.map((q) => `"${q}"`).join(", ")}`);
  opts.checkBudget?.(0.01);
  const r = await (opts.pick ?? sparkPick)(desc, ok);
  if (r.usd) opts.charge?.(r.usd, `find picture "${desc.slice(0, 60)}"`);
  const chosen = r.pick != null ? ok[r.pick] : undefined;
  if (!chosen) throw new Error(`findPicture "${desc}": no candidate shows it: ${r.reason}`);
  const full = await get(chosen.c.full);
  mkdirSync(dir, { recursive: true });
  const path = join(dir, `picture${extname(new URL(chosen.c.full).pathname).toLowerCase() || ".jpg"}`);
  writeFileSync(path, full);
  const [w, h] = dims(path);
  if (Math.min(w, h) < MIN_SIDE) {
    rmSync(dir, { recursive: true, force: true });
    throw new Error(`findPicture "${desc}": the pick "${chosen.c.title}" is only ${w}x${h}, too small to show`);
  }
  const found: Found = { path, title: chosen.c.title, source: chosen.c.source, license: chosen.c.license, credit: chosen.c.credit, page: chosen.c.page, why: r.reason };
  writeFileSync(meta, JSON.stringify(found, null, 1));
  return found;
}

// ---------------------------------------------------------------------------------------------------------------------

export type MakersOptions = Spend & {
  reasoner: Reasoner;
  image?: ImageMaker;
  segment?: Segmenter;
  study?: string;
  find?: Omit<FindOptions, keyof Spend>;
  pictureRoot?: string;
};

/** Both makers from one set of options, charged to the same place. */
export function metaDepictMakers(o: MakersOptions): DepictMakers {
  const spend: Spend = { charge: o.charge, checkBudget: o.checkBudget };
  return {
    sprite: metaSpriteMaker({ ...spend, image: o.image, segment: o.segment, study: o.study }),
    picture: async (desc, asset, parts = []) => {
      const pic = { ...spend, reasoner: o.reasoner, segment: o.segment, root: o.pictureRoot };
      if (asset) return pictureParts(asset, parts, pic, 3);
      const found = await findPicture(desc, { ...spend, ...o.find });
      return { ...(await pictureParts(found.path, parts, { ...pic, about: `${found.title} (${found.source}); wanted as: ${desc}` }, 4)), found };
    },
  };
}
